$quoteRoot=dirname(__DIR__,2).'/AdminQuote/src';require_once$quoteRoot.'/Application/ReadModel/QuoteCustomerSelection.php';require_once$quoteRoot.'/Contract/QuoteCustomerProviderInterface.php';require_once dirname(__DIR__).'/src/Integration/Quote/CustomerSelectionProvider.php';
use Flexgrid\Modules\AdminCore\ValueObject\TenantId;use Flexgrid\Modules\AdminCustomer\Domain\Model\Address;use Flexgrid\Modules\AdminCustomer\Domain\Model\Contact;use Flexgrid\Modules\AdminCustomer\Domain\Model\Customer;use Flexgrid\Modules\AdminCustomer\Domain\ValueObject\AddressType;use Flexgrid\Modules\AdminCustomer\Domain\ValueObject\CustomerStatus;use Flexgrid\Modules\AdminCustomer\Integration\Quote\CustomerSelectionProvider;
$customer=new Customer('customer-quote-provider',new TenantId('provider-tenant'),'Handelsnaam','Provider B.V.','12345678','NL001234567B01');$customer->addContact(new Contact('contact-quote-provider','Ada Admin','ada@example.test','030-1','Administratie',true,10));$customer->addAddress(new Address('address-quote-provider',new AddressType('billing'),'Markt 1','1000 AA','Utrecht','NL','Facturatie','Provider B.V.','','',true,10));$provider=new CustomerSelectionProvider();$method=new ReflectionMethod($provider,'selection');$method->setAccessible(true);$selection=$method->invoke($provider,$customer);adminCustomerAssert($selection->getPublicId()==='customer-quote-provider','Quote-provider moet publieke Customer-id leveren.');adminCustomerAssert($selection->getParty()['name']==='Provider B.V.'&&$selection->getParty()['contact_name']==='Ada Admin','Quote-provider moet partij en primair contact mappen.');adminCustomerAssert($selection->getBillingAddress()['city']==='Utrecht','Quote-provider moet primair factuuradres mappen.');$inactive=new Customer('customer-quote-inactive',new TenantId('provider-tenant'),'Inactief','','','',new CustomerStatus('inactive'));adminCustomerAssert($method->invoke($provider,$inactive)===null,'Inactieve klant mag niet selecteerbaar zijn.');$withoutAddress=new Customer('customer-quote-no-address',new TenantId('provider-tenant'),'Zonder adres');adminCustomerAssert($method->invoke($provider,$withoutAddress)===null,'Klant zonder primair factuuradres mag niet selecteerbaar zijn.');
